<template>
	<section class="cart-display" :class="{ split: mediaVisible, dense: state.items.length > 5 }" :style="{ '--receipt-width': `${receiptWidth}%` }">
		<div class="receipt">
			<header>
				<div class="brand"><img v-if="companyLogo" :src="companyLogo" alt="Company logo" /><div class="order-heading" :class="{ 'has-logo': companyLogo }"><p class="customer-name" :class="{ 'walk-in': isWalkInCustomer }">{{ customerLabel }}</p><p class="eyebrow">{{ copy.yourOrder }}</p></div></div>
				<div class="display-controls"><button v-if="!isFullscreen" class="icon-button" type="button" :title="copy.hideUrl" :aria-label="copy.hideUrl" @click="$emit('request-fullscreen')"><Maximize /></button><button class="icon-button" type="button" :title="mediaVisible ? copy.hideAdvertisement : copy.showAdvertisement" :aria-label="mediaVisible ? copy.hideAdvertisement : copy.showAdvertisement" @click="toggleMedia"><ChevronRight v-if="mediaVisible" /><ChevronLeft v-else /></button></div>
			</header>
			<main class="table-wrap"><table><thead><tr><th>{{ copy.product }}</th><th>{{ copy.quantity }}</th><th>{{ copy.price }}</th><th>{{ copy.lineTotal }}</th></tr></thead><tbody><tr v-for="item in state.items" :key="item.lineKey + (state.highlightedItemKey === item.lineKey ? `-${state.updatedAt}` : '')" :class="{ highlighted: highlightedItemKey === item.lineKey }"><td><strong>{{ item.name }}</strong><small v-if="item.variant">{{ item.variant }}</small><small v-if="item.discount > 0" class="saving">{{ copy.youSave }} RM{{ number(item.discount) }}</small></td><td>{{ item.quantity }}</td><td><span class="money"><small>RM</small>{{ number(item.rate) }}</span></td><td><s v-if="item.discount > 0"><span class="money"><small>RM</small>{{ number(item.rate * item.quantity) }}</span></s><strong><span class="money"><small>RM</small>{{ number(item.amount) }}</span></strong></td></tr></tbody></table></main>
			<footer><div class="summary"><span>{{ copy.subtotal }}</span><strong><span class="money"><small>RM</small>{{ number(state.subtotal) }}</span></strong></div><div v-if="state.itemDiscount > 0" class="summary saving"><span>{{ copy.itemDiscounts }}</span><strong>-<span class="money"><small>RM</small>{{ number(state.itemDiscount) }}</span></strong></div><div v-if="state.additionalDiscount > 0" class="summary saving"><span>{{ copy.additionalDiscount }}</span><strong>-<span class="money"><small>RM</small>{{ number(state.additionalDiscount) }}</span></strong></div><div v-if="state.tax > 0" class="summary"><span>{{ copy.tax }}</span><strong><span class="money"><small>RM</small>{{ number(state.tax) }}</span></strong></div><div class="total"><span>{{ copy.totalToPay }}</span><strong><span class="money"><small>RM</small>{{ number(state.grandTotal) }}</span></strong></div><div v-if="showChange && changeAmount > 0" class="change"><span>{{ copy.changeDue }}</span><strong><span class="money"><small>RM</small>{{ number(changeAmount) }}</span></strong></div></footer>
		</div>
		<button v-if="mediaVisible" class="split-handle" type="button" :aria-label="copy.resizeAdvertisement" @pointerdown="startResize"></button><aside v-if="mediaVisible" class="engagement"><IdleAdvertisement :language="language" /></aside>
	</section>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from "vue";
import { ChevronLeft, ChevronRight, Maximize } from "lucide-vue-next";
import type { CustomerDisplayState } from "@/services/customerDisplayChannel";
import IdleAdvertisement from "./IdleAdvertisement.vue";
defineEmits<{ "request-fullscreen": [] }>();
const props = defineProps<{ state: CustomerDisplayState; language: "en" | "ms"; isFullscreen: boolean }>();
const mediaVisible = ref(localStorage.getItem("xpos.customerDisplay.activeMedia") !== "false");
const receiptWidth = ref(readReceiptWidth());
const companyLogo = ref(localStorage.getItem("xpos.customerDisplay.companyLogo") || "");
const showChange = ref(localStorage.getItem("xpos.customerDisplay.showChange") !== "false");
const highlightedItemKey = ref("");
let highlightTimer: ReturnType<typeof setTimeout> | undefined;
const copy = computed(() => props.language === "ms" ? {
	yourOrder: "PESANAN ANDA", walkInCustomer: "Pelanggan Walk-in", welcome: "Selamat datang", product: "Produk", quantity: "Kuantiti", price: "Harga", lineTotal: "Jumlah", youSave: "Jimat", subtotal: "Jumlah Asal", itemDiscounts: "Diskaun Item", additionalDiscount: "Diskaun Tambahan", tax: "Cukai", totalToPay: "JUMLAH PERLU DIBAYAR", changeDue: "BAKI PERLU DIPULANGKAN", hideAdvertisement: "Sembunyi iklan", showAdvertisement: "Papar iklan", hideUrl: "Sembunyi URL", resizeAdvertisement: "Laraskan saiz iklan",
} : {
	yourOrder: "YOUR ORDER", walkInCustomer: "Walk-in Customer", welcome: "Welcome", product: "Product", quantity: "Qty", price: "Price", lineTotal: "Subtotal", youSave: "You save", subtotal: "Subtotal", itemDiscounts: "Item Discounts", additionalDiscount: "Additional Discount", tax: "Tax", totalToPay: "TOTAL TO PAY", changeDue: "CHANGE DUE", hideAdvertisement: "Hide advertisement", showAdvertisement: "Show advertisement", hideUrl: "Hide URL", resizeAdvertisement: "Adjust advertisement size",
});
const isWalkInCustomer = computed(() => !props.state.customerName || props.state.customerName === "Walk-in Customer");
const customerLabel = computed(() => isWalkInCustomer.value ? copy.value.walkInCustomer : `${copy.value.welcome}, ${props.state.customerName}`);
const changeAmount = computed(() => Math.max(0, Number(props.state.changeAmount) || 0));
watch(() => props.state.updatedAt, () => { const itemKey = props.state.highlightedItemKey; if (!itemKey) return; highlightedItemKey.value = itemKey; if (highlightTimer) clearTimeout(highlightTimer); highlightTimer = setTimeout(() => { highlightedItemKey.value = ""; }, 2000); }, { immediate: true });
onBeforeUnmount(() => { if (highlightTimer) clearTimeout(highlightTimer); });
function readReceiptWidth() { return Math.max(35, Math.min(80, Number(localStorage.getItem("xpos.customerDisplay.receiptWidth") || 60))); }
function toggleMedia() { mediaVisible.value = !mediaVisible.value; localStorage.setItem("xpos.customerDisplay.activeMedia", String(mediaVisible.value)); }
function startResize(event: PointerEvent) { const display = (event.currentTarget as HTMLElement | null)?.parentElement; if (!display) return; const resize = (move: PointerEvent) => { const bounds = display.getBoundingClientRect(); receiptWidth.value = Math.round(Math.max(35, Math.min(80, ((move.clientX - bounds.left) / bounds.width) * 100))); }; const stop = () => { localStorage.setItem("xpos.customerDisplay.receiptWidth", String(receiptWidth.value)); window.removeEventListener("pointermove", resize); window.removeEventListener("pointerup", stop); }; window.addEventListener("pointermove", resize); window.addEventListener("pointerup", stop, { once: true }); }
function syncSettings(event: StorageEvent) { if (event.key === "xpos.customerDisplay.activeMedia") mediaVisible.value = event.newValue !== "false"; if (event.key === "xpos.customerDisplay.receiptWidth") receiptWidth.value = readReceiptWidth(); if (event.key === "xpos.customerDisplay.companyLogo") companyLogo.value = event.newValue || ""; if (event.key === "xpos.customerDisplay.showChange") showChange.value = event.newValue !== "false"; }
window.addEventListener("storage", syncSettings);
onBeforeUnmount(() => window.removeEventListener("storage", syncSettings));
function number(value: number) { return new Intl.NumberFormat("en-MY", { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(Number(value || 0)); }
</script>

<style scoped>
