5vw,1.2rem);text-align:right;vertical-align:middle}td strong{display:block;font-size:clamp(.95rem,1.35vw,1.45rem);line-height:1.2}td small{display:block;margin-top:.18rem;color:#cbd5e1;font-size:clamp(.65rem,.85vw,.85rem)}td s{display:block;color:#94a3b8;font-size:.8em}.saving{color:#86efac!important;font-weight:700}.highlighted{animation:scanned-item 2s ease-out}.money{white-space:nowrap}.money small{display:inline;margin:0 .08em 0 0;font-size:.58em;font-weight:700;vertical-align:baseline}footer{padding-top:clamp(.55rem,1vw,1rem)}.summary{display:flex;justify-content:space-between;padding:.18rem 0;color:#cbd5e1;font-size:clamp(.8rem,1.1vw,1.15rem)}.total,.change{display:flex;justify-content:space-between;align-items:center;gap:.75rem;margin-top:.6rem;padding:.7rem 1rem;border-left:4px solid #fbbf24;background:rgb(251 191 36/.1);font-size:clamp(.85rem,1.3vw,1.35rem);font-weight:800}.total strong,.change strong{font-size:clamp(1.65rem,3.2vw,3.65rem);color:#fbbf24;white-space:nowrap}.total .money small,.change .money small{font-size:.42em}.change{margin-top:.45rem;border-left-color:#34d399;background:rgb(16 185 129/.12)}.change strong{color:#6ee7b7}.dense td{padding:.35rem}.dense td strong{font-size:clamp(.85rem,1.1vw,1.15rem)}.split-handle{z-index:2;flex:0 0 12px;margin:0 -6px;border:0;background:transparent;cursor:col-resize;touch-action:none}.split-handle::after{display:block;width:3px;height:100%;margin:auto;border-radius:2px;background:rgb(255 255 255/.3);content:""}.split-handle:hover::after,.split-handle:focus-visible::after{background:#fbbf24}.engagement{position:relative;display:flex;flex:1;min-width:0;overflow:hidden;border-left:1px solid rgb(255 255 255/.15)}@keyframes scanned-item{0%{background:rgb(134 239 172/.28);box-shadow:inset 6px 0 #86efac}100%{background:transparent;box-shadow:inset 0 0 transparent}}
</style>
